package com.circle.oog;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class EngineeringCalculationServiceTest {
    final ObjectMapper json=new ObjectMapper();
    EngineeringCalculationService.Input input(String source,Double cogX,EngineeringCalculationService.Support a,EngineeringCalculationService.Support b,EngineeringCalculationService.Lashing l){return new EngineeringCalculationService.Input(UUID.randomUUID(),source,"Measured weighing/CoG survey",5000d,cogX,1000d,1000d,a,b,l,"Static model input review");}
    EngineeringCalculationService.Support support(double x){return new EngineeringCalculationService.Support(x,100000d,1d,100d);}
    EngineeringCalculationService.Lashing lashing(double alpha){return new EngineeringCalculationService.Lashing("LONGITUDINAL",.8,1d,.3,10d,alpha,0d,4,"User verified route coefficient and weakest point effective capacity");}
    com.fasterxml.jackson.databind.JsonNode cargo()throws Exception{return json.readTree("{\"length\":10000,\"width\":2000,\"height\":3000,\"grossWeight\":5000}");}
    @Test void knownLeverRatiosSatisfyForceAndMomentEquilibriumAndCorrectPressureUnits()throws Exception{
        var result=EngineeringCalculationService.calculate(input("CONFIRMED",2000d,support(0),support(10000),lashing(30)),cargo());var supports=(Map<String,Object>)result.get("supports");var a=(Map<String,Object>)supports.get("A");var b=(Map<String,Object>)supports.get("B");
        assertThat((double)a.get("reactionKn")).isCloseTo(39.24,within(1e-10));assertThat((double)b.get("reactionKn")).isCloseTo(9.81,within(1e-10));assertThat((double)a.get("pressureMpa")).isCloseTo(.3924,within(1e-10));assertThat((double)supports.get("forceResidualKn")).isCloseTo(0,within(1e-10));assertThat((double)supports.get("momentResidualKnMm")).isCloseTo(0,within(1e-7));assertThat(result).containsEntry("eligibleForInternalApproval",true).containsEntry("carrierApproved",false);
    }
    @Test void midpointGivesEqualReactionsRegardlessSupportSpacing()throws Exception{var result=EngineeringCalculationService.calculate(input("CONFIRMED",5000d,support(2000),support(8000),lashing(30)),cargo());var s=(Map<String,Object>)result.get("supports");assertThat(((Map<String,Object>)s.get("A")).get("reactionKn")).isEqualTo(((Map<String,Object>)s.get("B")).get("reactionKn"));}
    @Test void outsideSupportIntervalReportsUpliftWithNoNegativeCompressionPressure()throws Exception{var result=EngineeringCalculationService.calculate(input("CONFIRMED",1000d,support(2000),support(8000),lashing(30)),cargo());var s=(Map<String,Object>)result.get("supports");assertThat(s).containsEntry("status","UPLIFT_OR_UNSTABLE");assertThat((Map<String,Object>)s.get("B")).containsEntry("pressureMpa",null);assertThat(result).containsEntry("eligibleForInternalApproval",false);}
    @Test void pressureAndReactionLimitsGateInternalApprovalIndependently()throws Exception{var lowPressure=new EngineeringCalculationService.Support(0d,100000d,.1,100d);var lowCapacity=new EngineeringCalculationService.Support(10000d,100000d,1d,1d);var result=EngineeringCalculationService.calculate(input("CONFIRMED",2000d,lowPressure,lowCapacity,lashing(30)),cargo());assertThat(result).containsEntry("status","FAILED_DECLARED_LIMITS").containsEntry("eligibleForInternalApproval",false);}
    @Test void missingLimitsAndUnknownLashingNeverDefaultToSafeValues()throws Exception{var missing=new EngineeringCalculationService.Support(0d,null,null,null);var result=EngineeringCalculationService.calculate(input("CONFIRMED",2000d,missing,support(10000),null),cargo());assertThat(result).containsEntry("status","INCOMPLETE").containsEntry("eligibleForInternalApproval",false);assertThat((Map<String,Object>)result.get("lashing")).containsEntry("status","INCOMPLETE");assertThat((List<String>)result.get("missingInputs")).contains("SUPPORT_A_AREA_AND_LIMITS","LASHING_DECLARED_COEFFICIENTS_CAPACITY_ANGLES_EVIDENCE");}
    @Test void lashingKnownDemandAndOrthogonalAngleProduceZeroDirectionalCapacity()throws Exception{var result=EngineeringCalculationService.calculate(input("CONFIRMED",2000d,support(0),support(10000),lashing(90)),cargo());var l=(Map<String,Object>)result.get("lashing");assertThat((double)l.get("externalForceKn")).isCloseTo(39.24,within(1e-10));assertThat((double)l.get("requiredDirectResistanceKn")).isCloseTo(24.525,within(1e-10));assertThat(l).containsEntry("availableDirectResistanceKn",0d).containsEntry("status","INSUFFICIENT_DECLARED_CAPACITY");}
    @Test void estimatedInputCanBeCalculatedButNeverInternallyApproved()throws Exception{var result=EngineeringCalculationService.calculate(input("ESTIMATED",2000d,support(0),support(10000),lashing(30)),cargo());assertThat(result).containsEntry("status","ESTIMATED_REQUIRES_CONFIRMATION").containsEntry("eligibleForInternalApproval",false);assertThatThrownBy(()->EngineeringCalculationService.validateDecision(1,2,json.valueToTree(result),"APPROVED_INTERNAL")).hasMessageContaining("승인할 수 없습니다");}
    @Test void selfApprovalForbiddenButIndependentReviewerCanApproveOnlyEligibleReport(){var eligible=json.createObjectNode().put("eligibleForInternalApproval",true);assertThatThrownBy(()->EngineeringCalculationService.validateDecision(1,1,eligible,"APPROVED_INTERNAL")).hasMessageContaining("스스로 승인");assertThatCode(()->EngineeringCalculationService.validateDecision(1,2,eligible,"APPROVED_INTERNAL")).doesNotThrowAnyException();assertThatCode(()->EngineeringCalculationService.validateDecision(1,1,eligible,"REQUEST_REVIEW")).doesNotThrowAnyException();}
    @Test void invalidSupportSpanZeroAreaNonfiniteAndOutsideCargoCogAreRejected()throws Exception{assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",2000d,support(100),support(100),lashing(30)),cargo())).hasMessageContaining("지지점 B");var zero=new EngineeringCalculationService.Support(0d,0d,1d,100d);assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",2000d,zero,support(10000),lashing(30)),cargo())).hasMessageContaining("수치 범위");assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",Double.NaN,support(0),support(10000),lashing(30)),cargo())).hasMessageContaining("수치 범위");assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",11000d,support(0),support(10000),lashing(30)),cargo())).hasMessageContaining("포장 외형");}
    @Test void vanishingSupportAreaAndSpanAreRejectedBeforeNumericalOverflow()throws Exception{
        var tinyArea=new EngineeringCalculationService.Support(0d,Double.MIN_VALUE,1d,100d);
        assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",2000d,tinyArea,support(10000),lashing(30)),cargo())).hasMessageContaining("수치 범위");
        assertThatThrownBy(()->EngineeringCalculationService.calculate(input("CONFIRMED",2000d,support(0),support(0.00001),lashing(30)),cargo())).hasMessageContaining("지지점 B");
    }
    @Test void differentMassCannotApproveDespiteNumericalPass()throws Exception{var heavier=json.readTree("{\"length\":10000,\"width\":2000,\"height\":3000,\"grossWeight\":8000}");var result=EngineeringCalculationService.calculate(input("CONFIRMED",2000d,support(0),support(10000),lashing(30)),heavier);assertThat(result).containsEntry("massMatchesSavedCargo",false).containsEntry("eligibleForInternalApproval",false);assertThatThrownBy(()->EngineeringCalculationService.validateDecision(1,2,json.valueToTree(result),"APPROVED_INTERNAL")).hasMessageContaining("승인할 수 없습니다");}
}
